import {tradeQuote,isEmbargoed,referenceUnitCost} from './economy-policy.js?v=43.1';
import {createEconomy} from './economy-core.js?v=43.1';
import {tradeGraph,createMarkets,atWar} from './economy-trade.js?v=43.1';
import {economicNodes} from './economy-rural.js?v=43.1';
import {seasonalVisitors} from './economy-society.js?v=43.1';
export const ECONOMY_STATE='silvengard-economy-state-v1';
const accountId=id=>/^(?:(?:city|province|state|carrier|service):\d+|rural:\d+:\d+)$/.test(id);
export function cleanEconomyState(raw,data){
 if(!raw)return {format:ECONOMY_STATE,cycle:0,elapsedDays:0,accounts:{},shipments:[],history:[],last:null};
 if(raw.format!==ECONOMY_STATE||!Number.isSafeInteger(raw.cycle)||raw.cycle<0||!raw.accounts||Object.keys(raw.accounts).length>3000)throw Error('Estado econômico inválido.');
 const goods=new Set(data.goods.map(g=>g.i)),accounts={};
 function quantities(rows,costs=false){const out={};for(const [g,n]of Object.entries(rows||{})){if(!goods.has(+g)||!Number.isFinite(n)||n<0||n>(costs?1e15:1e12))throw Error('Mercadoria em estoque inválida.');if(n>1e-10)out[g]=n;}return out;}
 for(const [id,a]of Object.entries(raw.accounts)){
  if(!accountId(id)||!Number.isSafeInteger(a.coins)||a.coins<0||a.coins>1e15||!a.stock||typeof a.stock!=='object')throw Error('Caixa ou estoque inválidos.');
  accounts[id]={coins:a.coins,stock:quantities(a.stock),stockCosts:quantities(a.stockCosts,true),assets:quantities(a.assets)};
 }
 const shipments=(raw.shipments||[]).map(t=>{if(!accountId(t.from)||!accountId(t.to)||!goods.has(t.good)||![t.units,t.cost,t.arrivalDay].every(n=>Number.isFinite(n)&&n>=0))throw Error('Carga em trânsito inválida.');return {from:t.from,to:t.to,good:t.good,units:t.units,cost:t.cost,arrivalDay:t.arrivalDay,routes:(t.routes||[]).filter(s=>typeof s==='string').slice(0,500)};});if(shipments.length>20000)throw Error('Cargas em trânsito demais.');
 let visits=0;function safe(v,depth=0){if(++visits>600000||depth>10)throw Error('Relatório econômico muito grande.');if(v==null||typeof v==='boolean')return v;if(typeof v==='number'){if(!Number.isFinite(v))throw Error('Número econômico inválido.');return v;}if(typeof v==='string'){if(v.length>300)throw Error('Texto econômico muito longo.');return v;}if(Array.isArray(v))return v.map(x=>safe(x,depth+1));if(typeof v==='object'){const out={};for(const [k,x]of Object.entries(v)){if(['__proto__','constructor','prototype'].includes(k))throw Error('Campo econômico inválido.');out[k]=safe(x,depth+1);}return out;}throw Error('Relatório inválido.');}
 const elapsedDays=raw.elapsedDays??raw.cycle*30;if(!Number.isFinite(elapsedDays)||elapsedDays<0)throw Error('Calendário econômico inválido.');
 return {format:ECONOMY_STATE,cycle:raw.cycle,elapsedDays,accounts,shipments,history:safe((raw.history||[]).slice(-24)),last:safe(raw.last||null)};
}
// The overview is a monthly run-rate. Saved cycles also record departure and arrival.
export function simulateEconomy(D,data,edits,raw,provinces,provinceAt,{instant=false}={}){
 const state=cleanEconomyState(raw,data),model=createEconomy(D,data,edits),nodes=economicNodes(D,data,model,provinces,provinceAt),start=state.elapsedDays,end=start+model.edits.cycleDays;
 const last={cycle:state.cycle+1,periodDays:model.edits.cycleDays,production:{},consumption:{},trades:[],demand:{},idle:{},piracyLoss:{},tariffRevenue:{},services:[],arrivals:[],newCapital:0,population:{residents:0,itinerants:0,rural:0,visitors:0}};
 const account=(id,pop=0)=>{if(!state.accounts[id]){const coins=Math.round(pop*model.edits.initialGoldPerResident*100);state.accounts[id]={coins,stock:{},stockCosts:{},assets:{}};last.newCapital+=coins;}return state.accounts[id];};
 for(const n of nodes.values()){n.account=account(n.id,n.population+(n.city?.seasonalVisitors||0));n.ready={};if(n.city){last.population.residents+=n.city.demographics.population;last.population.itinerants+=n.city.demographics.itinerantPopulation||0;last.population.visitors+=seasonalVisitors(n.city,state.cycle,model.edits.cycleDays);}else last.population.rural+=n.population;account('state:'+n.state);}
 const markets=createMarkets(D,data,model,{provinces,provinceAt,state,nodes});last.marketPrices=Object.fromEntries(markets.regions.map(m=>[m.i,Object.fromEntries(data.goods.map(g=>[g.i,markets.price(m.center,g.i)]))]));
 const {paths:distances,waterPaths}=tradeGraph(D,nodes,model.edits),price=(n,g)=>markets.price(n.city||n.cityReference,g),bump=(table,id,g,n)=>{table[id]??={};table[id][g]=(table[id][g]||0)+n;},stock=(n,g)=>n.account.stock[g]||0;
 const cost=(n,g)=>n.account.stockCosts[g]??stock(n,g)*referenceUnitCost(model,markets,n.city||n.cityReference,g);
 function take(n,g,units){const before=stock(n,g),previous=cost(n,g),removed=before?previous*Math.min(1,units/before):0;n.account.stock[g]=Math.max(0,before-units);n.account.stockCosts[g]=Math.max(0,previous-removed);return removed;}
 function addStock(n,g,units,totalCost,day=start){const previous=cost(n,g);n.account.stock[g]=stock(n,g)+units;n.account.stockCosts[g]=previous+totalCost;n.ready[g]=Math.max(n.ready[g]||start,day);}
 function produce(n,g,units,totalCost,day=start){if(units<=1e-8)return;addStock(n,g,units,totalCost??units*referenceUnitCost(model,markets,n.city||n.cityReference,g),day);bump(last.production,n.id,g,units);}
 for(const n of nodes.values())for(const g of Object.keys(n.account.stock))if(n.account.stockCosts[g]===undefined)n.account.stockCosts[g]=cost(n,+g);
 state.shipments=state.shipments.filter(t=>{const n=nodes.get(t.to);if(!n||t.arrivalDay>end)return true;addStock(n,t.good,t.units,t.cost,Math.max(start,t.arrivalDay));last.arrivals.push(t);return false;});
 const moneyBefore=Object.values(state.accounts).reduce((s,a)=>s+a.coins,0),trades=new Map(),inbound=(id,g)=>state.shipments.filter(t=>t.to===id&&t.good===g).reduce((s,t)=>s+t.units,0);
 const pathFor=(buyer,seller,g)=>(model.goods.get(g)?.transport?waterPaths:distances).get(buyer.id)?.get(seller.id);
 function serviceTransfer(payer,receiver,coins,type,detail={}){coins=Math.min(payer.coins,Math.max(0,Math.floor(coins)));if(!coins)return;payer.coins-=coins;account(receiver).coins+=coins;last.services.push({receiver,coins,type,...detail});}
 function procure(buyer,g,required){let missing=Math.max(0,required-stock(buyer,g)-inbound(buyer.id,g));if(missing<1e-8)return;const sellers=[];
  for(const seller of nodes.values()){if(seller.id===buyer.id||stock(seller,g)<1e-8)continue;const path=pathFor(buyer,seller,g);if(!path)continue;const quote=tradeQuote(D,model.edits,{sellerState:seller.state,buyerState:buyer.state,good:g,price:price(seller,g),cost:cost(seller,g)/stock(seller,g),path});if(quote)sellers.push({seller,path,quote});}sellers.sort((a,b)=>a.quote.delivered-b.quote.delivered||a.path.hours-b.path.hours);
  for(const {seller,path,quote:q}of sellers){
   if(missing<1e-8)break;const units=Math.min(missing/q.survival,stock(seller,g),q.shippedPrice>0?buyer.account.coins/(q.shippedPrice*100):Infinity);if(units<1e-8)continue;const paid=q.shippedPrice>0?Math.max(1,Math.ceil(units*q.shippedPrice*100-1e-9)):0;if(paid>buyer.account.coins)continue;
   const tariff=Math.min(paid,Math.floor(units*q.tariff*100+1e-9)),freight=Math.min(paid-tariff,Math.floor(units*q.freight*100+1e-9)),delivered=units*q.survival,lost=units-delivered,arrivalDay=instant?start:Math.max(start,seller.ready[g]||start)+(path.travelDays??path.hours/24);
   take(seller,g,units);buyer.account.coins-=paid;seller.account.coins+=paid-tariff-freight;
   if(freight){account('carrier:'+seller.state).coins+=freight;last.services.push({payer:buyer.id,receiver:'carrier:'+seller.state,coins:freight,type:'freight',routes:path.routes});}if(tariff){account('state:'+buyer.state).coins+=tariff;last.tariffRevenue[buyer.state]=(last.tariffRevenue[buyer.state]||0)+tariff;}
   const cargo={from:seller.id,to:buyer.id,good:g,units:delivered,cost:paid/100,arrivalDay,routes:path.routes};if(arrivalDay<=end)addStock(buyer,g,delivered,paid/100,arrivalDay);else state.shipments.push(cargo);if(lost>1e-8)bump(last.piracyLoss,buyer.id,g,lost);missing-=delivered;
   // Dock/broker/guild receipts have a payer. They are not free income from gross output.
   for(const [n,weight]of [[seller,1],[buyer,.5]]){const city=n.city||n.cityReference,cfg=data.cityServices?.[city?.i]||{},rate=(path.seaKm?cfg.dockRate||0:0)+(cfg.brokerRate||cfg.hospitalityRate||cfg.guildRate||0);if(city)serviceTransfer(seller.account,'service:'+city.i,(paid-tariff-freight)*rate*weight,'port-and-market',{payer:seller.id,city:city.i});}
   const tkey=buyer.id+'|'+seller.id+'|'+g;let row=trades.get(tkey);if(!row){row={from:seller.id,to:buyer.id,good:g,units:0,deliveredUnits:0,lostUnits:0,coins:0,tariffCoins:0,freightCoins:0,relation:q.relation,multiplier:q.multiplier,risk:q.risk,km:path.km,hours:path.hours,travelDays:path.travelDays||0,arrivalDay,roadKm:path.roadKm,seaKm:path.seaKm,routes:path.routes,market:markets.cityMarket(seller.city||seller.cityReference)?.i||0};trades.set(tkey,row);}row.units+=units;row.deliveredUnits+=delivered;row.lostUnits+=lost;row.coins+=paid;row.tariffCoins+=tariff;row.freightCoins+=freight;row.arrivalDay=Math.max(row.arrivalDay,arrivalDay);
  }
 }
 const jobs=[];for(const n of nodes.values()){if(n.province){for(const [g,units]of n.report.rural)produce(n,g,units);continue;}for(const j of n.report.jobs){if(!j.recipe.length)produce(n,j.good,j.capacity);else jobs.push({node:n,...j,done:0});}}
 const depths=new Map();function depth(g,visiting=new Set()){if(depths.has(g))return depths.get(g);if(visiting.has(g))return 0;const recipe=model.goods.get(g)?.recipes?.[0],n=recipe?1+Math.max(0,...Object.keys(recipe).map(id=>depth(+id,new Set([...visiting,g])))):0;depths.set(g,n);return n;}for(const j of jobs)j.depth=depth(j.good);jobs.sort((a,b)=>a.depth-b.depth||a.good-b.good);
 const demands=new Map(),scale=model.edits.cycleDays/30;
 for(const n of nodes.values()){const b=n.city,pop=n.population+(b?seasonalVisitors(b,state.cycle,model.edits.cycleDays):0),s=pop/1000*scale;demands.set(n.id,{food:s*model.edits.foodPer1000,utilities:s*.1,construction:s*.04,military:s*(b&&(b.citadel||b.settlementClass?.startsWith('Forte'))?.12:.025),luxury:s*(b?.capital||b?.magicSchool?.06:.025),research:s*(b?.magicSchool?.08:b?.capital?.005:.001),fleet:b?.majorPort?s*.03:0,inlandFleet:[3,13,120,191].includes(b?.i)?s*.04:0});last.demand[n.id]={};}
 for(const n of nodes.values())for(const [g,units]of Object.entries(n.account.assets)){const good=model.goods.get(+g),wear=units*(1-Math.pow(1-(good?.annualWear||.04),model.edits.cycleDays/365));n.account.assets[g]=Math.max(0,units-wear);bump(last.consumption,n.id,+g,wear);if(good?.transport)serviceTransfer(n.account,'service:'+(n.city?.i||n.cityReference?.i),wear*model.price(+g)*5,'repairs',{payer:n.id});}
 function consumeCategory(n,category){const need=demands.get(n.id);let left=need[category];if(left<1e-8)return;const options=data.goods.filter(g=>(g.demandCoverage?.[category]||0)>0||category==='military'&&[73,75,76].includes(g.i)).map(g=>({id:g.i,good:g,coverage:g.demandCoverage?.[category]||1})).sort((a,b)=>model.price(a.id)/a.coverage-model.price(b.id)/b.coverage);
  for(const g of options){if(left<1e-8)break;if(g.good.durable){const divisor=6/scale,installed=n.account.assets[g.id]||0;left=Math.max(0,left-installed*g.coverage/divisor);if(!left)continue;procure(n,g.id,left/g.coverage*divisor);const amount=Math.min(stock(n,g.id),left/g.coverage*divisor);if(amount>0){take(n,g.id,amount);n.account.assets[g.id]=installed+amount;left-=amount*g.coverage/divisor;}continue;}procure(n,g.id,left/g.coverage);const amount=Math.min(stock(n,g.id),left/g.coverage);if(amount<=1e-8)continue;take(n,g.id,amount);bump(last.consumption,n.id,g.id,amount);left-=amount*g.coverage;}need[category]=Math.max(0,left);
 }
 // Civilian/rural food goes ahead of industrial conversion. Stable ordering is deterministic.
 const foodOrder=[...nodes.values()].sort((a,b)=>a.id.localeCompare(b.id));for(const n of foodOrder)consumeCategory(n,'food');
 for(let round=0;round<12;round++){let progress=0;const tierNeed=new Map();for(const k of jobs)for(const r of k.recipe){const key=k.depth+':'+r.good;tierNeed.set(key,(tierNeed.get(key)||0)+Math.max(0,k.capacity-k.done)*r.units);}
  for(const j of jobs){const remaining=j.capacity-j.done;if(remaining<1e-8)continue;let target=remaining;for(const r of j.recipe){if(r.units<=0)continue;let available=0;for(const seller of nodes.values()){const path=pathFor(j.node,seller,r.good);if(path&&!atWar(D,model.edits,j.node.state,seller.state)&&!isEmbargoed(model.edits,j.node.state,seller.state,r.good))available+=stock(seller,r.good);}const demand=tierNeed.get(j.depth+':'+r.good)||0;target=Math.min(target,available/r.units,demand>available?remaining*available/demand:remaining);}if(target<1e-8)continue;
   for(const r of j.recipe)procure(j.node,r.good,target*r.units);let amount=target,day=start;for(const r of j.recipe)if(r.units>0){amount=Math.min(amount,stock(j.node,r.good)/r.units);day=Math.max(day,j.node.ready[r.good]||start);}if(amount<1e-8||day>end)continue;let inputCost=0;for(const r of j.recipe){const used=amount*r.units;inputCost+=take(j.node,r.good,used);bump(last.consumption,j.node.id,r.good,used);}produce(j.node,j.good,amount,inputCost+amount*model.price(j.good)*.15,day);j.done+=amount;for(const r of j.recipe){const key=j.depth+':'+r.good;tierNeed.set(key,Math.max(0,(tierNeed.get(key)||0)-amount*r.units));}progress+=amount;
  }if(progress<1e-8)break;
 }
 for(const n of foodOrder){for(const category of ['food','utilities','construction','military','luxury','research','fleet','inlandFleet'])consumeCategory(n,category);last.demand[n.id]=demands.get(n.id);}for(const j of jobs)if(j.capacity-j.done>1e-8)bump(last.idle,j.node.id,j.good,j.capacity-j.done);
 last.trades=[...trades.values()];last.transit=structuredClone(state.shipments);const moneyAfter=Object.values(state.accounts).reduce((s,a)=>s+a.coins,0);if(moneyAfter!==moneyBefore)throw Error('A contabilidade monetária não fechou.');
 const summary={cycle:last.cycle,tradeValue:last.trades.reduce((s,t)=>s+t.coins,0)/100,trades:last.trades.length,productionValue:Object.values(last.production).reduce((s,rows)=>s+Object.entries(rows).reduce((v,[g,n])=>v+n*model.price(+g),0),0),unmetFood:Object.values(last.demand).reduce((s,r)=>s+(r.food||0),0),capitalAdded:last.newCapital/100,tariffs:Object.values(last.tariffRevenue).reduce((s,n)=>s+n,0)/100,lostValue:Object.values(last.piracyLoss).reduce((s,rows)=>s+Object.entries(rows).reduce((v,[g,n])=>v+n*model.price(+g),0),0),inTransit:state.shipments.length,services:last.services.reduce((s,r)=>s+r.coins,0)/100};
 return cleanEconomyState({...state,elapsedDays:end,cycle:last.cycle,last,history:[...state.history,summary].slice(-24)},data);
}
